package com.alan.thormonitor;
public class WebRangeTest {static int checks;static void check(boolean v){if(!v)throw new AssertionError();checks++;}public static void main(String[] args)throws Exception{WebRange r=WebRange.parse("",100);check(!r.partial&&r.length()==100);r=WebRange.parse("bytes=20-29",100);check(r.partial&&r.start==20&&r.length()==10);r=WebRange.parse("bytes=-10",100);check(r.start==90&&r.length()==10);r=WebRange.parse("bytes=98-",100);check(r.length()==2);r=WebRange.parse("bytes=0-999",100);check(r.length()==100);check(WebRange.parse("",0).length()==0);for(String h:new String[]{"bytes=100-101","bytes=8-1","bytes=-0","bytes=0-1,2-3","nope","bytes=-","bytes=999999999999999999999999-"}){try{WebRange.parse(h,100);throw new AssertionError(h);}catch(IllegalArgumentException e){checks++;}}WebSessions sessions=new WebSessions();WebSessions.Session s=sessions.create("https://test",10);check(!s.id.equals(s.cookie)&&!s.id.equals(s.csrf));sessions.idleMinutes(60);check(sessions.get(s.cookie,s.origin,31*60000)!=null);check(sessions.revoke(s.id));check(sessions.get(s.cookie,s.origin,32*60000)==null);check(WebSessions.clientLabel("Mozilla Windows Chrome/123").equals("Chrome · Windows"));System.out.println(checks+" range/session checks passed");}}
